/* Glass surfaces are decorative; focus mode follows real topology links. */
(()=>{
 let focused=false;
 const tools=document.querySelector('.canvas-tool-right'),button=document.createElement('button');button.className='small-btn focus-network';button.id='focus-network';button.setAttribute('aria-pressed','false');button.title='Highlight the selected device and its direct connections';button.textContent='◎ Focus';tools.prepend(button);
 const viewport=document.querySelector('.topology-wrap'),fit=document.getElementById('fit-button');
 fit.classList.remove('icon-btn');fit.classList.add('small-btn');fit.setAttribute('aria-label','Fit entire topology');fit.textContent='Fit network';fit.title='Show every device and connection';
 function fitMap(){viewport.classList.add('overview-fit');zoom=1;renderTopology();viewport.scrollLeft=0;viewport.scrollTop=0;document.getElementById('zoom-label').textContent='Fit';}
 fit.onclick=fitMap;
 const readable=document.createElement('button');readable.className='small-btn';readable.textContent='Actual size';readable.title='View labels at full size; scroll to explore';fit.after(readable);
 readable.onclick=()=>{viewport.classList.remove('overview-fit');zoom=1;renderTopology();document.getElementById('zoom-label').textContent='100%';};
 function resizeMap(){const svg=document.getElementById('topology'),box=svg.viewBox.baseVal;const fitted=viewport.classList.contains('overview-fit');svg.style.setProperty('--map-width',(box.width*zoom)+'px');svg.style.setProperty('--map-height',(box.height*zoom)+'px');document.getElementById('zoom-label').textContent=fitted?'Fit':Math.round(zoom*100)+'%';}
 function zoomMap(factor){const box=document.getElementById('topology').viewBox.baseVal;const fitted=viewport.classList.contains('overview-fit');const current=fitted?Math.min(viewport.clientWidth/box.width,viewport.clientHeight/box.height):zoom;const cx=fitted?box.width*current/2:viewport.scrollLeft+viewport.clientWidth/2,cy=fitted?box.height*current/2:viewport.scrollTop+viewport.clientHeight/2;zoom=Math.max(.15,Math.min(2.5,current*factor));viewport.classList.remove('overview-fit');renderTopology();viewport.scrollLeft=Math.max(0,cx*zoom/current-viewport.clientWidth/2);viewport.scrollTop=Math.max(0,cy*zoom/current-viewport.clientHeight/2);}
 document.getElementById('zoom-in').onclick=()=>zoomMap(1.25);document.getElementById('zoom-out').onclick=()=>zoomMap(.8);
 const base=renderTopology;
 function decorate(){const device=engine.get(selected);if(!device)focused=false;const near=new Set(device?[device.id]:[]);if(device)for(const l of state.links){if(l.a===device.id)near.add(l.b);if(l.b===device.id)near.add(l.a);}document.querySelectorAll('[data-device]').forEach(node=>{node.classList.toggle('network-dimmed',focused&&!near.has(node.dataset.device));node.classList.toggle('network-neighbor',focused&&near.has(node.dataset.device));});document.querySelectorAll('[data-link]').forEach(node=>{const l=state.links.find(l=>l.id===node.dataset.link);node.classList.toggle('network-dimmed',focused&&l&&l.a!==selected&&l.b!==selected);node.classList.toggle('network-highlight',focused&&l&&(l.a===selected||l.b===selected));});button.disabled=!device;button.setAttribute('aria-pressed',String(focused));button.textContent=focused?'◎ Show all':'◎ Focus';const context=document.getElementById('topology-context');context.replaceChildren();const mark=document.createElement('span');mark.className='context-mark';mark.textContent=device?.type==='router'?'◎':device?.type==='switch'?'▤':'▣';const copy=document.createElement('span');copy.className='context-copy';const title=document.createElement('strong'),detail=document.createElement('small');title.textContent=device?.name||(state.lab?'Experiment '+String(state.lab).padStart(2,'0')+' · '+(experiments[state.lab-1]?.topic||'Custom lab'):'Network overview');detail.textContent=device?(device.type==='switch'?'Layer 2 switch':engine.address(device.id))+' · '+state.links.filter(l=>l.a===device.id||l.b===device.id).length+' connections':'Select a device to configure · Choose a scenario to practise a lab';copy.append(title,detail);context.append(mark,copy);if(!device&&state.lab){const guide=document.createElement('button');guide.className='context-config';guide.textContent='Lab guide ↗';guide.onclick=()=>guideModal(state.lab);context.append(guide);}if(device){const config=document.createElement('button');config.className='context-config';config.textContent='Configure ↗';config.onclick=()=>document.getElementById('inspector').scrollIntoView({behavior:'smooth',block:'start'});context.append(config);}}
 renderTopology=function(){base();resizeMap();decorate();};button.onclick=()=>{focused=!focused;decorate();};renderTopology();
})();
